public long CountInversionsBrute(int[] nums)
{
    long count = 0;

    for (int i = 0; i < nums.Length; i++)
    for (int j = i + 1; j < nums.Length; j++)
    {
        if (nums[i] > nums[j]) count++;
    }

    return count;
}

public long CountInversions(int[] nums)
{
    var buffer = new int[nums.Length];
    return Count(nums, buffer, 0, nums.Length - 1);
}

private static long Count(int[] nums, int[] buffer, int left, int right)
{
    if (left >= right) return 0;

    int mid = left + (right - left) / 2;

    long inversions = 0;
    inversions += Count(nums, buffer, left, mid);
    inversions += Count(nums, buffer, mid + 1, right);
    inversions += Merge(nums, buffer, left, mid, right);

    return inversions;
}

private static long Merge(int[] nums, int[] buffer, int left, int mid, int right)
{
    for (int i = left; i <= right; i++) buffer[i] = nums[i];

    int iLeft = left;
    int iRight = mid + 1;
    int write = left;
    long inversions = 0;

    while (iLeft <= mid && iRight <= right)
    {
        if (buffer[iLeft] <= buffer[iRight])
        {
            nums[write++] = buffer[iLeft++];
        }
        else
        {
            // buffer[iRight] is smaller than everything left in the left half
            inversions += mid - iLeft + 1;
            nums[write++] = buffer[iRight++];
        }
    }

    while (iLeft <= mid) nums[write++] = buffer[iLeft++];
    while (iRight <= right) nums[write++] = buffer[iRight++];

    return inversions;
}

public long CountInversions(int[] nums)
{
    var buffer = new int[nums.Length];
    return Count(nums, buffer, 0, nums.Length - 1);
}

private static long Count(int[] nums, int[] buffer, int left, int right)
{
    if (left >= right) return 0;
    int mid = left + (right - left) / 2;

    return Count(nums, buffer, left, mid)
         + Count(nums, buffer, mid + 1, right)
         + Merge(nums, buffer, left, mid, right);
}

private static long Merge(int[] nums, int[] buffer, int left, int mid, int right)
{
    Array.Copy(nums, left, buffer, left, right - left + 1);

    int iLeft = left, iRight = mid + 1, write = left;
    long inversions = 0;

    while (iLeft <= mid && iRight <= right)
    {
        if (buffer[iLeft] <= buffer[iRight]) nums[write++] = buffer[iLeft++];
        else { inversions += mid - iLeft + 1; nums[write++] = buffer[iRight++]; }
    }

    while (iLeft <= mid) nums[write++] = buffer[iLeft++];
    while (iRight <= right) nums[write++] = buffer[iRight++];
    return inversions;
}
